// Standalone design fixture. No API calls, authentication, or persistent learning storage.
const params=new URLSearchParams(location.search);
const pages={home:'今日',search:'查词',practice:'练习',session:'练习作答',review:'复习',reviewcard:'词卡自测',progress:'进度',library:'资料库',exam:'模考作答',examsetup:'模考预检',examresult:'模考结果',speaking:'口语练习',settings:'外观与偏好',compare:'四主题对照',states:'异常状态'};
const nav=[['home','今日','⌂'],['practice','练习','▷'],['review','复习','↻'],['progress','进度','▥'],['library','资料','▤']];
const themes={day:'日间',night:'夜间',hollow:'空洞骑士',silk:'丝之歌'};
const stateOptions={search:[['results','精确结果'],['initial','初始'],['input','输入中'],['loading','加载'],['related','相关匹配'],['empty','无结果'],['error','失败重试'],['detail','手机详情'],['long','长释义'],['adding','正在加入'],['added','已加入'],['add-error','加入失败']],home:[['default','今日任务'],['resume','已有未交卷模考'],['empty','首次使用'],['offline','离线记录']],session:[['default','未选择'],['selected','已选择'],['explanation','作答解析'],['save-error','保存失败'],['exit','退出确认']],review:[['default','到期队列'],['empty','暂无到期']],reviewcard:[['default','释义隐藏'],['revealed','已展开']],progress:[['default','有记录'],['empty','没有记录']],library:[['default','学习资料'],['local','本机题包'],['cloud','私人云题包'],['signed-out','原生身份边界'],['error','下载失败']],exam:[['default','作答中'],['exit','退出确认'],['save-error','保存失败']],examsetup:[['default','预检待试听'],['ready','已通过可开考'],['error','音频预检失败']],examresult:[['default','原始分与Part分析']],speaking:[['default','录音前'],['recording','录音中'],['permission','麦克风不可用']],settings:[['default','主题与数据边界'],['dialog','主题确认']],practice:[['default','听读'],['speaking','口语']],compare:[['default','相同今日页']],states:[['default','搜索和保存状态']]};
let page=pages[params.get('page')]?params.get('page'):'home';let theme=themes[params.get('theme')]?params.get('theme'):'day';let state=params.get('state')||'default';let query=params.get('query')||'schedule';let scope='dictionary';let selectedWord='schedule';let detailOpen=state==='detail'||state==='long';let resultScroll=0;let selectedOption='';let reviewRevealed=false;let lessonAdded=new Set();let composing=false;let toastTimer;
const words=[{word:'schedule',meaning:'日程表；计划；安排',pos:'名词 / 动词',ipa:'/ˈʃedjuːl/ · /ˈskedʒuːl/',source:'通用词典',defs:['日程表；按时间列出的安排。','安排时间；将活动纳入日程。'],example:'The meeting is scheduled for Friday.',translation:'会议安排在星期五。'},{word:'scheduled',meaning:'预定的；已安排的',pos:'形容词',ipa:'/ˈskedʒuːld/',source:'通用词典',defs:['按日程计划的；已安排的。'],example:'',translation:''},{word:'scheduler',meaning:'调度器；安排日程的人',pos:'名词',ipa:'',source:'通用词典',defs:['安排日程的人；执行任务调度的程序。'],example:'',translation:''},{word:'reschedule',meaning:'重新安排时间',pos:'动词',ipa:'/ˌriːˈskedʒuːl/',source:'通用词典',defs:['为活动重新安排时间。'],example:'',translation:''}];
function motif(kind){return kind==='hollow'?'<svg class="theme-motif hollow" viewBox="0 0 100 80" aria-hidden="true"><g fill="none" stroke="currentColor" stroke-width="1.2"><path d="M12 78V44Q12 8 50 8Q88 8 88 44V78M23 78V44Q23 21 50 21Q77 21 77 44V78M34 78V49Q34 33 50 33Q66 33 66 49V78"/><path d="M45 65Q38 45 38 39L45 44Q50 40 55 44L62 39Q62 45 55 65ZM46 53h2m5 0h2"/></g></svg>':'<svg class="theme-motif silk" viewBox="0 0 100 80" aria-hidden="true"><g fill="none" stroke="currentColor" stroke-width="1.2"><path d="M8 10Q93 13 57 40Q7 73 90 70M21 6Q83 5 73 44Q66 77 10 79M50 5v13M37 45Q37 18 50 18Q63 18 63 45L69 51H31Z"/><path d="M44 51q6 9 12 0M18 21l8 8m50 34l10 7"/></g></svg>';}
function header(title,sub,eyebrow='学习空间'){return `<div class="pagehead"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${sub}</p></div>${motif('hollow')}${motif('silk')}</div>`;}
function btn(label,target,primary=false,extra=''){let addedClass=extra.match(/class="([^"]*)"/);if(addedClass)extra=extra.replace(addedClass[0],'');return `<button type="button" class="button ${primary?'primary':''} ${addedClass?addedClass[1]:''}" ${target?`data-page="${target}"`:''} ${extra}>${label}</button>`;}
function task(n,title,desc,time,target){return `<div class="taskrow"><span class="step">${n}</span><div><h3>${title}</h3><p>${desc}</p></div><span class="duration">${time}</span><button class="arrow" data-page="${target}" ${title.startsWith('新学')?'data-next="scene"':title.startsWith('复练')?'data-next="review"':''} aria-label="打开${title}">→</button></div>`;}
function homeContent(){let resume=state==='resume';let empty=state==='empty';return header(empty?'从今天开始，慢慢积累。':'今天，先把一处卡点弄清楚。','10 月 13 日 · 听读优先 · 每日计划 25 分钟','今日')+(state==='offline'?'<div class="notice warning">当前离线 · 新记录保存在本机，恢复联网后再同步。</div>':'')+`<div class="columns"><section><div class="hero-task"><div class="row"><span class="tag">${empty?'今日起步':resume?'未交卷 · 截止时间保持':'到期复习 · 优先完成'}</span><span class="muted small">${resume?'阅读阶段':'约 5 分钟'}</span></div><h2>${empty?'先做一组短句填空':resume?'继续这一次模考':'先复习 8 个词'}</h2><p>${empty?'从 5 分钟开始。首答会单独记录，先了解自己的起点。':resume?'演示考试仍在计时。回到原题包和原截止时间，不重新开始。':'先回忆，再看解析。今天只需要弄懂一个错因。'}</p><div class="buttons">${btn(resume?'继续模考 →':empty?'开始 5 分钟 →':'开始复习 →',resume?'exam':empty?'session':'reviewcard',true)}${btn('今天只学 5 分钟','session',false,'class="button link"')}</div></div><div class="section-title"><h2>接下来</h2><span class="muted small">按余力选择</span></div>${empty?'':task('02','复练 3 道到期题','词卡与题目分别完成，记录分别保留','3 分钟','session')}${task('03','短句填空 · Part 5','完成一组新题，查看答案依据','10 分钟','session')}${task('04','新学 · 办公场景词','浏览场景词，自测前 20 个','7 分钟','search')}<div class="note"><strong>忙时做 5 分钟也算启动。</strong><br>漏一天，不累计补课债。口语练习保留在练习页。</div></section><aside><div class="panel compact-panel"><span class="small muted">今日学习</span><div class="metric" style="margin-top:12px">${empty?'0':'7'} <small>/ 25 分钟</small></div><div class="track"><span style="width:${empty?0:28}%"></span></div><div class="inline-status"><span class="dot"></span>${state==='offline'?'本机已保存 · 待同步':'学习记录已同步 · 网页'}</div><h3>近 7 天启动</h3><div class="week">${['三','四','五','六','日','一','二'].map((x,i)=>`<span class="${!empty&&[0,2,5,6].includes(i)?'done':i===6?'today':''}">${x}<b>${!empty&&[0,2,5,6].includes(i)?'✓':''}</b></span>`).join('')}</div><div class="note"><span class="muted">听读目标</span><br><strong>650+ · 12 月 20 日</strong><br><button class="button link compact" data-page="settings">调整学习偏好 →</button></div></div><div class="note"><strong>${empty?'尚无首次作答记录':'Part 5 首次正确率 40%'}</strong><br>${empty?'先完成一组新题，再看真实反馈。':'演示样例 · 5 次首答，样本较少。'}<br><button class="button link compact" data-page="progress">查看进度 →</button></div></aside></div>`;}
function searchDetail(){let w=words.find(x=>x.word===selectedWord)||words[0];let added=lessonAdded.has(w.word)||state==='added';let adding=state==='adding';return `<div class="detail"><button class="detail-back" data-action="back-results">← 返回结果 · 保留查询</button><div class="row"><span class="tag neutral">${scope==='scene'?'托业场景词 · 办公事务':'通用词典 · 非托业专用词表'}</span></div><h2 class="word-title">${state==='long'?'pneumonoultramicroscopicsilicovolcanoconiosis':w.word}</h2><div class="row"><span class="phonetic">${w.ipa||'暂无音标'}</span><button class="iconbtn" aria-label="${scope==='scene'?'播放场景词发音':'通用词典无内置音频'}" ${scope==='scene'?'data-action="audio"':'disabled'}>♬</button></div><div class="definition"><b>${w.pos}</b>${w.defs.map((x,i)=>`<p>${i+1}. ${x}</p>`).join('')}${state==='long'?'<p>3. 长释义、词形和来源按阅读顺序展开；中文自然换行，英文词头允许断行。内容可滚动，底部操作不遮住最后一行。</p>'.repeat(5):''}</div>${w.example&&scope==='scene'?`<div class="example"><span>${w.example}</span><small>${w.translation}</small></div>`:'<div class="notice">此通用词条不保证提供例句或离线发音。可有内容才显示。</div>'}<div class="buttons space"><button class="button primary" data-action="add-word" ${adding?'disabled':''}>${adding?'正在加入…':added?'✓ 已加入生词本':'＋ 加入生词本'}</button>${added?btn('去词卡自测','reviewcard')+btn('移出生词本',null,false,'data-action="remove-word"'):''}</div>${state==='add-error'?'<div class="notice error" role="alert"><strong>加入未成功</strong><p>原记录保持不变。请重试，不显示成功状态。</p><button class="button compact" data-action="retry-add">重新加入</button></div>':''}<div class="source space">${scope==='scene'?'场景词释义和例句为项目原创。':'数据来源：中文维基词典 / Kaikki · CC BY-SA 4.0。通用词例为设计演示文案，不替代实际源词条。'}<br>${scope==='scene'?'场景词可提供内置合成发音。':'通用词典无全库内置发音；系统朗读仅在实际设备支持时开放。'}<br>收藏后才进入生词和词卡复习，不因搜索自动新增学习记录。</div></div>`;}
function searchBody(){if(['initial','input','loading','empty','error'].includes(state)){let texts={initial:['从一个词开始','支持英文词头、词形与中文释义。通用词典和场景词分开检索。'],input:['输入完整后再查找','中文输入法组词期间不刷新结果。完成输入后展示匹配。'],loading:['正在加载英汉词典','首次加载较大。输入保留，校验通过后即可检索。'],empty:[`未找到“${query||'appelp'}”`,'试试完整词头或中文释义。当前没有拼写纠错，不自动替换你的输入。'],error:['词典加载失败','查询已保留。重试同一份词典；场景词仍可单独使用。']};let t=texts[state];return `<div class="panel empty" role="${state==='error'?'alert':'status'}"><span class="empty-symbol">${state==='loading'?'◌':state==='error'?'!':'⌕'}</span><h2>${escapeHTML(t[0])}</h2><p>${t[1]}</p>${state==='loading'?'<div class="skeleton"></div><div class="skeleton short"></div>':''}${state==='error'?'<div class="buttons">'+btn('重试加载',null,true,'data-action="retry-search"')+btn('改查场景词',null,false,'data-action="scene"')+'</div>':''}${state==='empty'?btn('清空查询',null,false,'data-action="clear"'):''}</div>`;}
let list=words.filter(x=>`${x.word} ${x.meaning}`.toLowerCase().includes(query.trim().toLowerCase()));if(state==='related')list=words;if(state==='long')list=words;if(!list.length)return `<div class="panel empty"><span class="empty-symbol">⌕</span><h2>未找到“${escapeHTML(query)}”</h2><p>当前仅支持精确和相关匹配，不提供自动拼写纠错。</p>${btn('清空查询',null,false,'data-action="clear"')}</div>`;return `<div class="search-layout ${detailOpen?'detail-open':''}"><div class="results"><div class="result-label">${list.length} 个结果 · 精确词头优先</div>${list.map(x=>`<button class="wordrow ${selectedWord===x.word?'selected':''}" data-word="${x.word}" ${selectedWord===x.word?'aria-current="true"':''}><span><b>${x.word}</b><small>${x.meaning}</small><small>${x.pos}</small></span><span class="match-tag">${x.word===query.trim().toLowerCase()?'精确':'相关'}</span></button>`).join('')}<div class="result-label">相关匹配 = 前缀、词内或释义<br>不含拼写纠错</div></div>${searchDetail()}</div>`;}
function searchContent(){return header('查词','找到词义，再决定要不要学。','词汇')+`<div class="segmented" aria-label="词汇范围"><button data-scope="scene" class="${scope==='scene'?'active':''}" aria-pressed="${scope==='scene'}">托业场景词</button><button data-scope="dictionary" class="${scope==='dictionary'?'active':''}" aria-pressed="${scope==='dictionary'}">英汉查词</button></div><label class="search-field"><span class="icon" aria-hidden="true">⌕</span><input id="word-query" type="search" aria-label="搜索单词或中文释义" placeholder="输入单词或中文释义" value="${escapeHTML(state==='initial'?'':state==='input'?'sche':state==='empty'?'appelp':state==='related'?'sche':query)}" enterkeyhint="search" autocapitalize="off" autocomplete="off" spellcheck="false"><button class="iconbtn" aria-label="清空查询" data-action="clear">×</button></label><div class="filterline"><button class="chip active" aria-pressed="true">全部</button><button class="chip" data-action="my-words" aria-pressed="false">我的生词</button>${scope==='scene'?'<button class="chip" data-action="scene">办公事务 ▾</button>':''}<span style="margin-left:auto">${scope==='scene'?'807 场景词 + 55 题内表达':'84,979 条 · 通用词典'}</span></div><div id="search-body">${searchBody()}</div>`;}
function practiceContent(){return header('练习','一次专心完成一组，再理解答案依据。','训练')+`<div class="segmented"><button class="${state==='speaking'?'':'active'}" data-action="lr">听力与阅读</button><button class="${state==='speaking'?'active':''}" data-action="speaking-tab">口语表达</button></div>${state==='speaking'?`<div class="panel space"><h2>录音 · 回听 · 自评</h2><p class="muted space">保留朗读、图片描述、回答问题等现有五类任务。当前学习目标优先听读。</p><div class="buttons space">${btn('开始朗读练习','speaking',true)}</div></div>`:`<div class="section-title"><h2>按 Part 练习</h2><span class="muted small">68 道原创起步题</span></div><div class="part-list">${['照片描述','应答问题','简短对话','简短独白','短句填空','长文填空','阅读理解'].map((x,i)=>`<div class="partrow"><span class="part-number">PART ${i+1}</span><div><h3>${x}</h3><p>${i===4?'首次 2 / 5 · 样本较少':'尚无首次记录'}</p></div><button class="arrow" aria-label="开始${x}" data-page="session">→</button></div>`).join('')}</div><div class="grid2 space"><div class="panel"><span class="tag neutral">完整计时</span><h2 class="space">听读模考</h2><p class="muted small space">使用个人 200 题题包，音频与图像预检后开考。考试记录仅本机。</p>${btn('选择题包 →','library',false,'style="margin-top:18px" data-next="local"')}</div><div class="panel"><span class="tag neutral">词汇学习</span><h2 class="space">场景词与词卡</h2><p class="muted small space">按场景浏览。收藏成为生词，词卡自测进入复习节奏。</p>${btn('浏览场景词 →','search',false,'style="margin-top:18px" data-next="scene"')}</div></div>`}`;}
function sessionContent(){let explain=state==='explanation';let choice=selectedOption||(state==='selected'?'B':'');return `<div class="question"><div class="session-toolbar"><button class="quiet" data-action="exit-session">← 退出练习</button><div>Part 5 · 短句填空<br><span class="small">第 3 / 5 题 · 演示</span></div></div><div class="panel"><div class="row"><span class="tag neutral">新题首答</span><span class="muted small">2 道已提交</span></div><h1 class="question-stem" lang="en">The meeting has been ______ until Friday because the manager is away.</h1>${[['A','postpone'],['B','postponed'],['C','postponing'],['D','postponement']].map(([letter,word])=>`<button class="option ${choice===letter?'active':''} ${explain&&letter==='B'?'correct':''}" data-option="${letter}" aria-pressed="${choice===letter}" ${explain?'disabled':''}><span class="letter">${letter}</span><span lang="en">${word}</span>${explain&&letter==='B'?'<span style="margin-left:auto">✓ 正确答案</span>':''}</button>`).join('')}${explain?'<div class="analysis"><div class="answer">✓ 答案 B · 已提交答案保留</div><p>has been 后接过去分词，构成现在完成时的被动语态。“会议被推迟”，选择 postponed。</p><div class="example">has been + 过去分词<small>这次首答与之后复练分别记录。</small></div><button class="button link" data-page="search" data-query="schedule">查相关词 →</button></div>':''}${state==='save-error'?'<div class="notice error" role="alert"><strong>提交未保存</strong><p>选项仍在当前页。请重试成功后再离开。</p></div>':''}<div class="session-actions"><span class="inline-status">${explain?'答案已提交 · 演示；时间在完成题组后打卡':'先作答，再看解析'}</span>${btn(explain?'下一题 →':state==='save-error'?'重试提交':'提交答案',null,true,`${!explain&&!choice&&state!=='save-error'?'disabled':''} data-action="submit-answer"`)}</div></div></div>`;}
function reviewContent(){let empty=state==='empty';return header('复习','把学过的变成能想起来的。','到期与错题')+(empty?'<div class="panel empty"><span class="empty-symbol">✓</span><h2>今天没有到期复习</h2><p>可以去练一组新题，或浏览场景词。提前反复作答不会提高复习间隔。</p>'+btn('去练习','practice',true)+'</div>':`<div class="grid2"><div class="panel"><div class="review-count"><strong>8</strong><span>个到期生词<br><small class="muted">先回忆词义，再揭晓</small></span></div>${btn('开始词卡自测','reviewcard',true)}</div><div class="panel"><div class="review-count"><strong>3</strong><span>道到期题目<br><small class="muted">先复练，再看上次解析</small></span></div>${btn('开始题目复练','session',false)}</div></div><div class="section-title"><h2>优先巩固</h2><span class="muted small">已保存记录</span></div><div class="part-list">${task('P5','短句填空','首次作答出错 · 到期复练','2 道','session')}${task('P2','应答问题','到期复练 · 答案与听力依据','1 道','session')}</div><div class="notice">首答、复练分别保留。立即再做不升级间隔，也不覆盖原成绩。</div>`);}
function reviewCardContent(){let revealed=state==='revealed'||state==='save-error'||reviewRevealed;return `<div class="question"><div class="session-toolbar"><button class="quiet" data-action="exit-review">← 返回复习</button><span>词卡自测 · 2 / 8<br><small>一张一张，慢慢想起来</small></span></div><div class="panel review-card"><span class="tag neutral">办公事务 · 演示词卡</span><h1 class="word-title" lang="en">schedule</h1><span class="phonetic">/ˈʃedjuːl/ · /ˈskedʒuːl/</span>${revealed?'<p class="meaning">日程表；计划；安排</p><p class="muted small">The meeting is scheduled for Friday.</p>':'<p class="muted space">先在心里回忆词义</p>'}<div class="buttons space" style="justify-content:center">${revealed?btn('还不熟',null,false,'data-action="grade-word"')+btn('记住了 →',null,true,'data-action="grade-word"'):btn('查看释义',null,true,'data-action="reveal"')}</div><div class="source space">只记录明确的自测反馈；退出后保留已完成词卡。<br>未完成词卡不假设为已掌握。</div></div></div>`;}
function progressContent(){let empty=state==='empty';return header('进度','看真实的记录，找到下一步。','学习反馈')+`<div class="statgrid"><div class="stat"><span class="small muted">近 7 天学习</span><div class="metric">${empty?'—':'62'} <small>${empty?'':'分钟'}</small></div><p>${empty?'尚无记录':'按已完成打卡累计'}</p></div><div class="stat"><span class="small muted">近 7 天启动</span><div class="metric">${empty?'0':'4'} <small>/ 4 天目标</small></div><p>未完成天数不形成补课债</p></div><div class="stat"><span class="small muted">模考基线</span><div class="metric">—</div><p>尚未完成首次完整模考</p></div></div><div class="columns"><section class="panel"><div class="row"><h2>各 Part 首次正确率</h2><span class="tag neutral">首答</span></div><p class="muted small" style="margin-top:8px">${empty?'完成首次作答后，这里才出现数据。':'复练不覆盖首次。样本不足时只提示，不作分数预测。'}</p>${[1,2,3,4,5,6,7].map(x=>`<div class="chart-row ${x!==5||empty?'no-data':''}"><span>Part ${x}</span><div class="track"><span style="width:${x===5&&!empty?'40':'0'}%"></span></div><span class="num">${x===5&&!empty?'40% · 2/5':'暂无记录'}</span></div>`).join('')}<div class="notice">${empty?'暂无可判断的薄弱 Part。先完成一组新题。':'Part 5 样本较少。建议再完成一组新题，观察是否仍卡在词形。'}</div>${btn('练习 Part 5','session',true)}</section><aside class="panel compact-panel"><h2>一周节奏</h2><div class="trend" role="img" aria-label="演示近七天学习分钟：12、0、18、0、0、25、7"><div><b>${empty?'0':'12'}</b><i style="height:${empty?0:48}%"></i><span>三</span></div><div><b>0</b><i style="height:0"></i><span>四</span></div><div><b>${empty?'0':'18'}</b><i style="height:${empty?0:72}%"></i><span>五</span></div><div><b>0</b><i style="height:0"></i><span>六</span></div><div><b>0</b><i style="height:0"></i><span>日</span></div><div><b>${empty?'0':'25'}</b><i style="height:${empty?0:100}%"></i><span>一</span></div><div><b>${empty?'0':'7'}</b><i style="height:${empty?0:28}%"></i><span>二</span></div></div><div class="note"><strong>我的卡点手记</strong><br>${empty?'完成练习后的打卡中可记录想法。':'演示样例：完成时被动语态的词形。'}<br>手记保留现有打卡能力，不新增题目标记接口。</div>${btn('导出周复盘',null,false,'data-action="demo-export"')}</aside></div>`;}
function libraryContent(){let tab=['local','cloud','signed-out','error'].includes(state)?state==='local'?'local':'cloud':'resources';return header('资料库','学习资料、私人题包，各有自己的去处。','资源')+`<div class="segmented"><button class="${tab==='resources'?'active':''}" data-library="resources">学习资料</button><button class="${tab==='local'?'active':''}" data-library="local">本机题包</button><button class="${tab==='cloud'?'active':''}" data-library="cloud">私人云库</button></div>${tab==='resources'?`<div class="filterline"><button class="chip active">全部</button><button class="chip" data-action="resource-filter">听力</button><button class="chip" data-action="resource-filter">阅读</button><button class="chip" data-action="resource-filter">口语</button></div><div class="panel"><h2>选一份，做 5–15 分钟</h2>${[['ETS 官方学习入口','查看官方题型与样例 · 外部资料'],['British Council · 商务英语','听一段职场对话，复述两句 · 免费资料'],['BBC Learning English','理解一段短音频，记录一个表达 · 免费资料']].map(([title,desc])=>`<div class="resource"><span class="resource-icon">▤</span><div><h3>${title}</h3><p>${desc}</p><span class="tag neutral">外链 · 保留来源</span></div><button class="button compact" data-action="open-resource">查看 ↗</button></div>`).join('')}</div><div class="notice">资料打开和学习打卡是两个动作。资源完成后沿用现有打卡，不新增计划编辑。</div>`:tab==='local'?`<div class="notice"><strong>本机题包 · 考试记录仅此设备</strong><p>导入校验后的完整 200 题包。题包云库不代表考试记录已同步。</p></div><div class="panel"><div class="row"><h2>已导入题包</h2>${btn('导入 JSON',null,false,'data-action="import-demo"')}</div><div class="resource"><span class="resource-icon">200</span><div><h3>示例题包 · 现行听读</h3><p>200 题 · 45 分钟听力 / 75 分钟阅读</p><span class="tag neutral">已校验 · 演示内容</span></div>${btn('预检','examsetup',false,'class="button compact"')}</div><div class="resource"><span class="resource-icon">200</span><div><h3>示例题包 · 2006 旧题型</h3><p>单独 Part 结构及评分 · 不混为现行题型</p><span class="tag neutral">私人来源 · 演示内容</span></div>${btn('预检','examsetup',false,'class="button compact"')}</div><div class="source space">演示占用 42 / 192 MiB · 实际上限保持。已有考试记录的题包不可移除。</div></div><div class="buttons space">${btn('导出考试备份',null,false,'data-action="demo-export"')}${btn('恢复考试备份',null,false,'data-action="exam-restore"')}</div>`:state==='signed-out'?`<div class="panel empty"><span class="empty-symbol">↗</span><h2>通过系统浏览器访问私人云库</h2><p>原生 App 当前没有云端身份。浏览器登录下载 JSON 后，再回 App 导入；本机考试不云同步。</p>${btn('打开浏览器入口',null,true,'data-action="browser-demo"')}</div>`:`<div class="notice"><strong>私人云题包 · 仅当前网页账号</strong><p>上传 / 下载题包。学习数据同步、词库备份和考试备份分别管理。</p></div>${state==='error'?'<div class="notice error" role="alert"><strong>题包下载失败 · 本机原题库未变</strong><p>保留已导入题包，重试本次下载。</p>'+btn('重新下载',null,false,'data-action="retry-cloud"')+'</div>':''}<div class="panel"><div class="row"><h2>私人云库</h2>${btn('上传 JSON',null,false,'data-action="upload-demo"')}</div>${[['示例私人题包 A','现行题型 · 36.9 MiB'],['示例私人题包 B','2006 旧题型 · 29.4 MiB']].map(([title,desc])=>`<div class="resource"><span class="resource-icon">▤</span><div><h3>${title}</h3><p>${desc}</p><span class="tag neutral">仅当前账号 · 演示</span></div><button class="button compact" data-action="download-demo">下载</button></div>`).join('')}<div class="source space">不预装、搬运或公开私人题本。保留版本、来源与完整校验。</div></div>`}`;}
function examContent(){return `<div class="question"><div class="session-toolbar"><button class="quiet" data-action="exit-exam">← 保存并退出</button><div>听读模考 · 阅读阶段<br><strong class="timer">01:12:36</strong></div></div><div class="notice warning">退出后继续计时 · 演示剩余时间固定；实际以原截止时间计算。</div><div class="panel"><div class="row"><span class="tag neutral">现行题型 · Part 5</span><span class="small muted">第 103 / 200 题</span></div><h1 class="question-stem" lang="en">The office will be closed ______ the public holiday.</h1>${[['A','during'],['B','among'],['C','between'],['D','toward']].map(([l,w])=>`<button class="option ${selectedOption===l?'active':''}" data-option="${l}" aria-pressed="${selectedOption===l}"><span class="letter">${l}</span><span lang="en">${w}</span></button>`).join('')}${state==='save-error'?'<div class="notice error" role="alert">答案保存失败 · 保留当前选项，重试成功后再离开。</div>':''}<div class="session-actions"><span class="inline-status">${state==='save-error'?'本题未保存 · 请重试':'本机自动保存 · 演示'}</span><div class="buttons">${btn('上一题',null,false,'data-action="exam-next"')}${btn('下一题 →',null,true,'data-action="exam-next"')}</div></div><details class="space"><summary>题号导航 · 已答 / 未答</summary><div class="keygrid">${Array.from({length:20},(_,i)=>`<button class="${i===2?'active':i<2?'answered':''}" data-action="exam-next" aria-label="第${101+i}题${i<2?' 已答':' 未答'}">${101+i}</button>`).join('')}</div></details></div></div>`;}
function examSetupContent(){let ready=state==='ready';return header('开考前，先确认材料完整。','预检完成不会开始计时；明确开考才建立原截止时间。','模考')+`<div class="question panel"><span class="tag neutral">示例题包 · 现行听读 · 200 题</span><h2 class="space">材料与计时预检</h2><div class="settingrow"><div><h3>题包结构与校验</h3><p>题号、答案映射与来源</p></div><span class="tag">✓ 通过</span></div><div class="settingrow"><div><h3>全部题图</h3><p>解码成功，无缺图</p></div><span class="tag">✓ 通过</span></div><div class="settingrow"><div><h3>完整听力音轨</h3><p>真实媒体时长与声明一致</p></div><span class="tag ${state==='error'?'error':''}">${state==='error'?'! 失败':'✓ 通过'}</span></div>${state==='error'?'<div class="notice error" role="alert">实际音轨短于声明 · 暂不能开考。原题包保留，请重新核对材料。</div>':'<div class="settingrow"><div><h3>人耳试听确认</h3><p>确认听得见且设备输出正常</p></div><button class="button compact" data-action="hear">试听演示</button></div>'}<label class="settingrow"><span class="small">我已亲自试听，确认音频可用</span><input type="checkbox" id="hear-confirm" ${ready?'checked':''} ${state==='error'?'disabled':''}></label><div class="notice warning">听力 45 分钟 + 阅读 75 分钟。退出不暂停；原截止时间和首次 / 复测标记保持。</div>${btn('开始这一次考试','exam',true,`${!ready?'disabled':''} id="start-exam"`)}</div>`;}
function examResultContent(){return header('这一次模考，已经完成。','看原始答对题数与各 Part 表现，再决定下一次练什么。','模考复盘')+`<div class="statgrid"><div class="stat"><span class="muted small">听力原始答对</span><div class="metric">62 <small>/ 100</small></div><p>演示样例 · 不替代官方换算分</p></div><div class="stat"><span class="muted small">阅读原始答对</span><div class="metric">57 <small>/ 100</small></div><p>演示样例 · 不预测考试分数</p></div><div class="stat"><span class="muted small">记录位置</span><div class="metric" style="font-size:28px">仅本机</div><p>本次为首次；复測另存</p></div></div><div class="panel"><h2>Part 分析</h2>${[['Part 1',67,'4/6'],['Part 5',40,'12/30'],['Part 7',56,'30/54']].map(([x,v,n])=>`<div class="chart-row"><span>${x}</span><div class="track"><span style="width:${v}%"></span></div><span class="num">${v}% · ${n}</span></div>`).join('')}<div class="buttons space">${btn('查看错题解析','session',true)}${btn('导出考试备份',null,false,'data-action="demo-export"')}</div><div class="source space">本图仅示意版式；正式结果必须由当前题包题型与 Part 分布计算，不能使用示意分母。</div></div>`;}
function speakingContent(){return header('朗读 · 图书馆通知','准备、录音、回听，只改一个地方。','口语')+`<div class="question panel"><div class="row"><span class="tag neutral">Read a text aloud · 演示任务</span><span class="timer">${state==='recording'?'00:18':'00:45'}</span></div><p lang="en" class="question-stem">Please note that the library will close at six o'clock this evening. Regular opening hours will resume tomorrow.</p>${state==='permission'?'<div class="notice error" role="alert"><strong>麦克风当前不可用</strong><p>检查设备权限。没有成功录音时不显示已保存。</p></div>':''}<div class="buttons space">${btn(state==='recording'?'停止录音并保存':'开始录音',null,true,'data-action="record-demo"')}${btn('返回练习','practice',false)}</div><div class="source space">设计演示不请求麦克风权限。正式实现沿用真实录音与发生时间，保存成功后才可回放 / 导出。</div></div>`;}
function themeCards(){return `<div class="themegrid">${Object.entries(themes).map(([id,name])=>`<button class="theme-card ${id===theme?'selected':''}" data-theme-pick="${id}" aria-pressed="${id===theme}"><div class="theme-preview" data-theme="${id}"><div class="mini-rail"></div><div class="mini-body"><b></b><i></i><i></i><em></em></div>${['hollow','silk'].includes(id)?motif(id):''}</div><div><span>${name}${id===theme?' ✓':''}</span><small class="muted">${id==='day'?'暖白 · 墨绿':id==='night'?'炭灰 · 薄荷':id==='hollow'?'冷墨蓝 · 骨白':'暖墨 · 莓红'}</small></div></button>`).join('')}</div>`;}
function settingsContent(){return header('外观与偏好','四种气质，同一个学习空间。','设置')+`<div class="columns"><section><h2 style="margin-bottom:18px">界面主题</h2>${themeCards()}<div class="notice">日间与夜间无游戏元素。主题只改变视觉，学习记录、目标与题包保持。</div><div class="panel space"><div class="settingrow"><div><h3>简短交互动效</h3><p>按压 / 展开反馈；系统减少动态优先</p></div><button class="toggle" role="switch" aria-label="简短交互动效" aria-checked="true" data-action="toggle"></button></div><div class="settingrow"><div><h3>游戏主题装饰</h3><p>仅页边缘小幅静态图案，专注题面无装饰</p></div><span class="tag neutral">静态</span></div><div class="settingrow"><div><h3>每日学习预算</h3><p>演示 25 分钟 · 沿用已有偏好编辑</p></div>${btn('编辑',null,false,'class="button compact" data-action="edit-profile"')}</div></div></section><aside class="panel compact-panel"><h2>数据与设备</h2><div class="settingrow"><div><h3>网页学习记录</h3><p>当前账号同步 · 离线队列</p></div></div><div class="settingrow"><div><h3>词库与生词</h3><p>独立 JSON 备份</p></div></div><div class="settingrow"><div><h3>模考与题包</h3><p>记录仅本机 · 另行完整备份</p></div></div><div class="settingrow"><div><h3>私人云库</h3><p>题包上传 / 下载，按账号隔离</p></div></div><button class="button compact" data-action="demo-export">现有导出入口</button><div class="source space">原生 App 不显示已云同步。手机号登录未配置时保持关闭。不新增学习 JSON 恢复 UI。</div></aside></div>`;}
function compareContent(){return header('相同今日页，四种完整主题。','布局、组件与语义共用；游戏表达仅留在标题边缘。','主题规范')+`<div class="comparison">${Object.entries(themes).map(([id,name])=>`<section class="sample" data-theme="${id}"><div class="row"><h2>${name}</h2>${id==='hollow'||id==='silk'?motif(id):'<span class="muted small">无游戏元素</span>'}</div><div class="hero-task"><div class="row"><span class="tag">到期复习</span><span class="muted small">5 分钟</span></div><h2>先复习 8 个词</h2><p>先回忆，再看解析。今天弄懂一处卡点。</p><div class="buttons">${btn('开始复习 →','reviewcard',true)}</div></div>${task('02','短句填空 · Part 5','一组新题，查看答案依据','10 分钟','session')}<div class="notice error">示例错误状态 · 加入失败，请重试</div><label class="search-field"><span class="icon">⌕</span><input readonly value="schedule" aria-label="${name}主题输入示例"></label></section>`).join('')}</div>`;}
function statesContent(){return header('异常状态，也保持清晰。','保留输入、选择与旧数据，让下一步明确。','状态组件')+`<div class="state-list"><div class="statecard"><h3>初始 · 搜索</h3><p class="muted small">输入单词或中文释义。场景词与通用词典明确分开。</p><label class="search-field"><span class="icon">⌕</span><input placeholder="输入单词或中文释义" aria-label="初始搜索示例"></label></div><div class="statecard" role="status"><h3>加载 · 查询保留</h3><p class="muted small">正在加载英汉词典… 首次加载较大。</p><div class="skeleton"></div><div class="skeleton short"></div></div><div class="statecard"><h3>无结果 · 不假装纠错</h3><div class="notice">未找到“appelp”。试试完整词头或中文释义。</div>${btn('重新输入','search')}</div><div class="statecard" role="alert"><h3>失败 · 可重试</h3><div class="notice error">词典加载失败。输入“schedule”已保留。</div>${btn('重试加载','search',true)}</div><div class="statecard"><h3>加入生词本 · 独立状态</h3><div class="buttons">${btn('正在加入…',null,true,'disabled')}${btn('✓ 已加入',null,false)}</div><div class="notice error">加入未成功 · 原记录保持，不显示假成功。</div></div><div class="statecard" role="alert"><h3>练习提交 · 保存失败</h3><p class="small muted">选项 B 保留在当前页；重试成功后再离开。</p><div class="notice error">未保存 ≠ 已同步。不要用绿色提示掩盖失败。</div>${btn('重试提交','session',true)}</div><div class="statecard"><h3>离线 · 学习记录</h3><div class="notice warning">本机已保存，待联网同步。</div><p class="small muted">仅网页学习记录；原生始终提示本机。</p></div><div class="statecard"><h3>暂无数据 · 进度</h3><div class="metric">—</div><p class="small muted">尚无首次记录，不绘制假曲线或考试预测分。</p></div></div>`;}
function escapeHTML(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function render(){document.documentElement.dataset.theme=theme;document.body.classList.toggle('focus-mode',['session','reviewcard','exam','speaking'].includes(page));document.getElementById('breadcrumb').textContent=`学习空间 / ${pages[page]}`;document.getElementById('desktop-nav').innerHTML=nav.map(([id,label,icon])=>`<button class="navitem ${page===id?'selected':''}" data-page="${id}" ${page===id?'aria-current="page"':''}><span class="icon" aria-hidden="true">${icon}</span><span>${label}</span>${id==='review'?'<span class="badge">11</span>':''}</button>`).join('')+`<button class="navitem ${page==='search'?'selected':''}" data-page="search" ${page==='search'?'aria-current="page"':''}><span class="icon" aria-hidden="true">⌕</span><span>查词</span></button>`;document.getElementById('mobile-nav').innerHTML=nav.map(([id,label,icon])=>`<button class="${page===id?'selected':''}" data-page="${id}" ${page===id?'aria-current="page"':''}><span class="icon" aria-hidden="true">${icon}</span>${label}</button>`).join('');document.getElementById('page-control').innerHTML=Object.entries(pages).map(([id,label])=>`<option value="${id}" ${id===page?'selected':''}>${label}</option>`).join('');document.getElementById('theme-control').value=theme;const states=stateOptions[page];document.getElementById('state-control').innerHTML=states.map(([id,label])=>`<option value="${id}" ${id===state?'selected':''}>${label}</option>`).join('');const contents={home:homeContent,search:searchContent,practice:practiceContent,session:sessionContent,review:reviewContent,reviewcard:reviewCardContent,progress:progressContent,library:libraryContent,exam:examContent,examsetup:examSetupContent,examresult:examResultContent,speaking:speakingContent,settings:settingsContent,compare:compareContent,states:statesContent};document.getElementById('content').innerHTML=(contents[page]||window.designExtras?.[page]||homeContent)();history.replaceState(null,'',`?page=${page}&theme=${theme}&state=${state}`);if(page==='search'){const input=document.getElementById('word-query');input.addEventListener('compositionstart',()=>composing=true);input.addEventListener('compositionend',()=>{composing=false;handleInput(input.value)});input.addEventListener('input',()=>{if(!composing)handleInput(input.value)});input.addEventListener('keydown',e=>{if(e.key==='Enter'&&!e.isComposing&&!composing)handleInput(input.value)});if(state==='related')query='sche';if(state==='empty')query='appelp';}if(['exit','dialog'].includes(state))showModal();}
function handleInput(value){query=value;state=value.trim()?'results':'initial';detailOpen=false;let matches=words.filter(x=>`${x.word} ${x.meaning}`.toLowerCase().includes(value.trim().toLowerCase()));if(matches.length&&!matches.some(x=>x.word===selectedWord))selectedWord=matches[0].word;document.getElementById('search-body').innerHTML=searchBody();replaceIcons();}
let sessionOrigin='practice';let searchOrigin={page:'home',state:'default',scroll:0};let searchReturnQuery='schedule';function navigate(target,next){if(target==='session'){sessionOrigin=page==='review'?'review':page==='examresult'?'mock-review':'practice';}if(target==='search'&&page!=='search'){searchOrigin={page,state,scroll:window.scrollY};searchReturnQuery=query;}if(page==='search')resultScroll=window.scrollY;page=target;state=next||stateOptions[target][0][0];if(target==='search'&&next==='scene'){scope='scene';state='results';}detailOpen=false;render();window.scrollTo(0,0);}
function toast(message){const el=document.getElementById('toast');el.textContent=message;el.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('visible'),3200);}
function showModal(){document.querySelector('.modal-cover')?.remove();let exam=page==='exam';let themeDialog=page==='settings';let text=themeDialog?'主题预览只影响演示界面。正式实现仅更新 theme 字段，保留已有目标与设置。':exam?'先保存本次状态，再退出。考试继续计时，原截止时间不变；保存失败时留在当前页重试。':'2 道已提交答案保留。当前未提交选项与题组位置不持久保存；重新进入将重开题组。学习时间在完成题组后打卡。';document.body.insertAdjacentHTML('beforeend',`<div class="modal-cover" role="dialog" aria-modal="true" aria-labelledby="modal-title"><div class="modal"><h2 id="modal-title">${themeDialog?'主题切换':exam?'保存并退出模考？':'退出这组练习？'}</h2><p>${text}</p><div class="buttons"><button class="button" data-action="cancel-exit">${themeDialog?'完成':'继续作答'}</button>${themeDialog?'':btn(exam?'保存并退出':'退出并保留首答',null,true,'data-action="confirm-exit"')}</div></div></div>`);document.querySelector('.modal [data-action="cancel-exit"]').focus();}
document.addEventListener('change',e=>{if(e.target.id==='page-control')navigate(e.target.value);if(e.target.id==='theme-control'){theme=e.target.value;render();}if(e.target.id==='state-control'){state=e.target.value;detailOpen=state==='detail'||state==='long';selectedOption=state==='selected'||state==='save-error'?'B':'';reviewRevealed=state==='revealed';render();}if(e.target.id==='hear-confirm')document.getElementById('start-exam').disabled=!e.target.checked;});
document.addEventListener('click',e=>{const target=e.target.closest('button,a');if(!target)return;if(target.dataset.page){e.preventDefault();let next=target.dataset.next;if(target.dataset.query)query=target.dataset.query;navigate(target.dataset.page,next);return;}if(target.dataset.word){resultScroll=window.scrollY;selectedWord=target.dataset.word;detailOpen=true;state='detail';document.getElementById('search-body').innerHTML=searchBody();if(innerWidth<=700)window.scrollTo(0,0);return;}if(target.dataset.scope){scope=target.dataset.scope;state='results';render();return;}if(target.dataset.themePick){theme=target.dataset.themePick;render();toast('演示主题已切换 · 学习数据保持');return;}if(target.dataset.option){selectedOption=target.dataset.option;render();return;}if(target.dataset.library){state=target.dataset.library==='resources'?'default':target.dataset.library;render();return;}switch(target.dataset.action){case'back-results':detailOpen=false;state='results';document.getElementById('search-body').innerHTML=searchBody();window.scrollTo(0,resultScroll);break;case'clear':query='';state='initial';detailOpen=false;render();document.getElementById('word-query').focus();break;case'scene':scope='scene';state='results';render();break;case'retry-search':state='results';render();break;case'add-word':lessonAdded.add(selectedWord);state='added';document.getElementById('search-body').innerHTML=searchBody();toast('演示：已加入生词本');break;case'retry-add':lessonAdded.add(selectedWord);state='added';render();break;case'my-words':toast(lessonAdded.size?'演示：筛选当前已收藏词':'演示：生词本为空，加入后才能复习');break;case'audio':toast('演示按钮 · 此原型不播放或请求音频');break;case'lr':state='default';render();break;case'speaking-tab':state='speaking';render();break;case'submit-answer':if(state==='explanation'){state='default';selectedOption='';render();toast('演示：进入下一题');}else{state='explanation';selectedOption=selectedOption||'B';render();}break;case'exit-session':state='exit';showModal();break;case'exit-exam':state='exit';showModal();break;case'cancel-exit':document.querySelector('.modal-cover')?.remove();state='default';break;case'confirm-exit':document.querySelector('.modal-cover')?.remove();navigate(page==='exam'?'library':'practice',page==='exam'?'local':undefined);toast('演示返回 · 未操作真实数据');break;case'exit-review':navigate('review');break;case'reveal':reviewRevealed=true;state='revealed';render();break;case'grade-word':reviewRevealed=false;state='default';render();toast('演示反馈已记录 · 原型没有持久存储');break;case'toggle':target.setAttribute('aria-checked',target.getAttribute('aria-checked')!=='true');break;case'hear':toast('原型不播放声音，也不自动勾选人耳确认');break;case'exam-next':toast('演示题号切换 · 实际答案按现有存储保存');break;case'record-demo':state=state==='recording'?'default':'recording';render();toast('仅录音状态演示，不申请麦克风');break;case'retry-cloud':state='cloud';render();break;case'demo-export':toast('演示导出入口 · 不读写实际备份');break;case'exam-restore':toast('沿用现有模考恢复入口 · 此原型不选择文件');break;case'open-resource':toast('外链与材料打卡保留现有能力 · 演示不打开外站');break;case'resource-filter':toast('演示资料筛选 · 正式实现沿用现有分类');break;case'edit-profile':toast('沿用已有偏好编辑，主题更新不提交完整默认 profile');break;default:if(target.dataset.action)toast('仅设计演示 · 不上传、下载或修改真实内容');}});
document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'&&!['exam','session','speaking','reviewcard'].includes(page)){e.preventDefault();navigate('search');document.getElementById('word-query').focus();}if(e.key==='Escape'&&document.querySelector('.modal-cover')){document.querySelector('.modal-cover').remove();state='default';}if(e.key==='Tab'&&document.querySelector('.modal-cover')){const controls=[...document.querySelector('.modal').querySelectorAll('button')];if(e.shiftKey&&document.activeElement===controls[0]){e.preventDefault();controls.at(-1).focus();}else if(!e.shiftKey&&document.activeElement===controls.at(-1)){e.preventDefault();controls[0].focus();}}});
const iconPaths={'⌂':'<path d="m3 10 9-7 9 7v10H3Z"/><path d="M9 20v-7h6v7"/>','▷':'<path d="m7 4 13 8-13 8Z"/>','↻':'<path d="M20 8a8 8 0 1 0 0 8M20 3v5h-5"/>','▥':'<path d="M4 20V4M4 20h17M8 17v-5M13 17V7M18 17V4"/>','▤':'<path d="M4 4h16v16H4Z"/><path d="M8 8h8M8 12h8M8 16h5"/>','⌕':'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/>','◐':'<circle cx="12" cy="12" r="8"/><path d="M12 4v16"/>'};
function replaceIcons(){const originBack=document.querySelector('.search-origin-back');if(originBack)originBack.textContent='← 返回'+(searchOrigin.page==='session'&&searchOrigin.state==='explanation'?'练习解析':pages[searchOrigin.page]);document.querySelectorAll('.word-title,.phonetic').forEach(x=>x.setAttribute('lang','en'));document.querySelector('#search-body .empty')?.setAttribute('role','status');document.querySelectorAll('.result-label').forEach(x=>{x.setAttribute('role','status');x.setAttribute('aria-live','polite');});document.querySelector('[data-action="add-word"]')?.setAttribute('aria-pressed',String(lessonAdded.has(selectedWord)||state==='added'));document.querySelector('.themegrid')?.setAttribute('role','group');document.querySelector('.themegrid')?.setAttribute('aria-label','选择界面主题');document.body.classList.toggle('detail-mode',page==='search'&&detailOpen);document.querySelectorAll('.icon,.iconbtn').forEach(el=>{const code=el.textContent.trim();if(iconPaths[code])el.innerHTML=`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${iconPaths[code]}</svg>`;});}
const baseRender=render;render=function(){if(page==='search'&&state==='related')query='sche';baseRender();document.body.classList.toggle('search-mode',page==='search');if(page==='home'&&state==='empty')document.querySelector('.badge')?.remove();replaceIcons();};
document.addEventListener('click',()=>{replaceIcons();});
stateOptions.search.push(['mine-empty','我的生词为空'],['due-empty','无到期词']);
stateOptions.session.push(['review','题目复练'],['mock-review','模考解析']);
const originalSearchBody=searchBody;searchBody=function(){if(state==='mine-empty'||state==='due-empty')return `<div class="panel empty" role="status"><span class="empty-symbol">${state==='mine-empty'?'☆':'✓'}</span><h2>${state==='mine-empty'?'生词本还是空的':'这个范围没有到期词'}</h2><p>词典已加载成功。筛选结果为空，不代表加载失败；原收藏与复习记录保留。</p>${btn('查看全部',null,true,'data-action="all-words"')}</div>`;return originalSearchBody();};
const originalSearchContent=searchContent;searchContent=function(){return originalSearchContent().replace('<button class="chip active" aria-pressed="true">全部</button>',`<button class="chip ${!['mine-empty','due-empty'].includes(state)?'active':''}" data-action="all-words" aria-pressed="${!['mine-empty','due-empty'].includes(state)}">全部</button>`).replace('<button class="chip" data-action="my-words" aria-pressed="false">我的生词</button>',`<button class="chip ${state==='mine-empty'?'active':''}" data-action="my-words" aria-pressed="${state==='mine-empty'}">我的生词</button><button class="chip ${state==='due-empty'?'active':''}" data-action="due-words" aria-pressed="${state==='due-empty'}">到期复习</button>`);};
stateOptions.session.push(['complete','题组完成'],['checkin','记录时间与收获'],['checkin-saved','打卡保存成功']);
stateOptions.review.push(['due-zero','到期 0 · 仍有错题']);
stateOptions.reviewcard.push(['save-error','词卡保存失败'],['complete','词卡结束']);
const questionRenderer=sessionContent;
sessionContent=function(){if(state==='complete')return `<div class="question panel"><span class="tag neutral">短句填空 · 5 道原创题</span><h1 class="space">这一组，完成了。</h1><div class="metric space">3 <small>/ 5 答对 · 演示</small></div><p class="muted space">答案已提交。原创样题不换算为正式分数；首答和复练分别保留。</p><div class="notice">练习时间尚未打卡。可以记录实际分钟与收获，也可以先休息；已提交答案保留。</div><div class="buttons space">${btn('记录时间与收获',null,true,'data-action="open-checkin"')}${btn('先休息一下','practice')}</div></div>`;if(state==='checkin')return `<div class="question panel"><h1>记录时间与收获</h1><p class="muted space">只记录这次实际学习。取消打卡不撤销已提交答案。</p><form class="simple-form"><label>实际学习分钟<input type="number" min="1" max="240" step="1" value="5" required id="checkin-minutes" aria-label="实际学习分钟"></label><fieldset class="space" style="border:0;padding:0"><legend>今天的负荷</legend><div class="buttons"><label><input type="radio" name="load" value="light"> 轻</label><label><input type="radio" name="load" value="right" checked> 刚好</label><label><input type="radio" name="load" value="heavy"> 重</label></div></fieldset><label>一个收获或卡点 · 可选<textarea maxlength="1000" placeholder="例如：弄清了现在完成时的被动语态" aria-label="一个收获或卡点"></textarea></label><div class="buttons space">${btn('保存打卡',null,true,'data-action="save-checkin"')}${btn('暂不记录','practice')}</div></form></div>`;if(state==='checkin-saved')return `<div class="question panel empty"><span class="empty-symbol">✓</span><h1>时间与收获已记录</h1><p class="space">演示成功状态。真实页面须等待已有打卡保存返回成功，才显示此状态。</p><div class="buttons space">${btn('回到今日','home',true)}${btn('查看解析','session',false,'data-next="explanation"')}</div></div>`;let html=questionRenderer();if(sessionOrigin==='review'||state==='review')html=html.replace('新题首答','题目复练 · 首答记录保留');return html;};
const reviewRenderer=reviewContent;reviewContent=function(){if(state==='due-zero')return header('今天没有到期复习。','错题仍然保留，可以按余力复练。','复习')+`<div class="notice">到期题目 0 · 到期词卡 0。提前复练不抬高间隔。</div><div class="panel"><h2>还有 3 道错题可巩固</h2>${task('P5','短句填空','既往首次错误 · 当前未到期','3 道','session')}<div class="buttons space">${btn('查看并复练','session',true)}${btn('去做新题','practice')}</div></div>`;return reviewRenderer();};
const cardRenderer=reviewCardContent;reviewCardContent=function(){if(state==='complete')return `<div class="question panel empty"><span class="empty-symbol">✓</span><h1>这一组词卡，完成了。</h1><p class="space">8 张词卡已明确反馈 · 演示。题目复练是另一条队列，不自动标为完成。</p><div class="buttons space">${btn('返回复习','review',true)}${btn('复练到期题目','session')}</div></div>`;if(state==='save-error')return cardRenderer()+`<div class="question notice error" role="alert"><strong>词卡反馈未保存</strong><p>保留当前词卡和选项，重试成功再进入下一张；不显示“已掌握”。</p>${btn('重试保存',null,false,'data-action="retry-card"')}</div>`;return cardRenderer();};
const regularSessionContent=sessionContent;sessionContent=function(){if(state==='mock-review'||sessionOrigin==='mock-review')return `<div class="question"><div class="session-toolbar"><button class="quiet" data-page="examresult">← 返回模考结果</button><span>本机示例题包 A · 第 103 题<br>现行题型 · Part 5</span></div><div class="panel"><span class="tag neutral">模考解析 · 保留原考试上下文</span><h1 class="question-stem" lang="en">The office will be closed ______ the public holiday.</h1><p class="answer">正确答案 A · during</p><p class="space">during 后接时间段，表示“在……期间”。本页只浏览原考试解析，不把模考错题写为普通新题首答。</p><div class="source space">原题包、题号、首次 / 复测与截止时间保持。本机考试记录不云同步。</div></div></div>`;return regularSessionContent();};
document.addEventListener('submit',e=>e.preventDefault());
document.addEventListener('keydown',e=>{if(e.key==='Escape')requestAnimationFrame(()=>document.querySelector(`[data-action="${page==='exam'?'exit-exam':'exit-session'}"]`)?.focus({preventScroll:true}));});
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;const action=b.dataset.action;if(action==='remove-word'){e.stopImmediatePropagation();lessonAdded.delete(selectedWord);state='results';render();toast('演示：已移出生词本，旧学习记录不删除');return;}if(action==='my-words'){e.stopImmediatePropagation();state=lessonAdded.size?'results':'mine-empty';render();return;}if(action==='all-words'){e.stopImmediatePropagation();state='results';render();return;}if(action==='due-words'){e.stopImmediatePropagation();state='due-empty';render();return;}if(action==='return-origin'){e.stopImmediatePropagation();page=searchOrigin.page;state=searchOrigin.state;render();window.scrollTo(0,searchOrigin.scroll);return;}if(action==='open-checkin'){e.stopImmediatePropagation();state='checkin';render();return;}if(action==='save-checkin'){e.preventDefault();e.stopImmediatePropagation();if(document.getElementById('checkin-minutes').checkValidity()){state='checkin-saved';render();}return;}if(action==='retry-card'){e.stopImmediatePropagation();state='revealed';render();return;}},{capture:true});
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.action==='back-results')document.querySelector(`[data-word="${selectedWord}"]`)?.focus({preventScroll:true});if(b.dataset.option)document.querySelector(`[data-option="${selectedOption}"]`)?.focus({preventScroll:true});if(b.dataset.themePick)document.querySelector(`[data-theme-pick="${theme}"]`)?.focus({preventScroll:true});if(['cancel-exit'].includes(b.dataset.action))document.querySelector(`[data-action="${page==='exam'?'exit-exam':'exit-session'}"]`)?.focus({preventScroll:true});document.querySelectorAll('.result-label').forEach(x=>{x.setAttribute('role','status');x.setAttribute('aria-live','polite');});document.querySelector('[data-action="add-word"]')?.setAttribute('aria-pressed',String(lessonAdded.has(selectedWord)||state==='added'));});
render();

